    detectSecrets,
    detectSecretsRegen,
    detectSecretsRescan,
    hokusai,
    localPaletteDev,
    localPaletteDevStop,
    postCommit,
    postMerge,
    preCommit,
    prePush,
    prReview,
    retainCommit,
