  env: { NODE_ENV: "production", SESSION_LOCAL_INSECURE: "true", NODE_PATH: "src" },
  data: [srcs, relayArtifacts, data.schema, packageJson, build],
  readiness: { http: "http://localhost:4000/health", timeout: "90s" },
