import { Smithers as S } from "@smthrs/targets"
import { Package as src } from "../src/PACKAGE.js"

const vocsConfig = S.file("vocs.config.ts")

const srcs = S.Filegroup({
  srcs: S.glob(["**", "!dist/**", "!.cache/**", "!pages.gen.ts"]),
})

// gen:token-lookup derives the docs token table from src/tokens.
const tokenLookup = S.Generate({
  bin: S.NodeModule.Bin("bun"),
  args: ["scripts/generateTokenLookup.ts"],
  data: [src.srcs],
  changes: ["data/tokens.ts"],
})

// The docs build consumes the declaration emit: vocs twoslash resolves
// viem imports in every snippet against the real types.
const build = S.Shell.Build({
  bin: S.NodeModule.Bin("vocs"),
  args: ["build"],
  env: { NODE_OPTIONS: "--max-old-space-size=6144" },
  data: [srcs, src.srcs, src.buildTypes, tokenLookup, vocsConfig],
  outDirs: ["dist"],
})

// Every fenced code block in the docs compiles or the target fails: the
// documentation is a type-checked artifact, not prose beside the code.
const twoslash = S.Shell.Test({
  bin: S.NodeModule.Bin("vocs"),
  args: ["twoslash"],
  data: [srcs, src.srcs, src.buildTypes, vocsConfig],
})

const dev = S.Shell.Serve({
  bin: S.NodeModule.Bin("vocs"),
  args: ["dev"],
  data: [srcs, src.srcs, src.buildTypes, tokenLookup, vocsConfig],
  readiness: { port: 5173 },
})

const preview = S.Shell.Serve({
  bin: S.NodeModule.Bin("vocs"),
  args: ["preview"],
  data: [build],
  readiness: { port: 4173 },
})

export const Package = S.Package({
  targets: { build, dev, preview, srcs, tokenLookup, twoslash },
})

/// <reference path="../smithers.d.ts" />
import { Smithers as S } from "@smthrs/targets"

const packageJson = S.file("package.json")
const buildTsconfig = S.file("//tsconfig.build.json")
const baseTsconfig = S.file("//tsconfig.base.json")

const srcs = S.Filegroup({
  srcs: S.glob([
    "**",
    "!**/*.test.ts",
    "!**/*.test-d.ts",
    "!**/*.bench.ts",
    "!**/*.bench-d.ts",
    "!_cjs/**",
    "!_esm/**",
    "!_types/**",
  ]),
})

// Tests are colocated with the source; the vitest projects in
// //test:PACKAGE.ts consume this group.
const tests = S.Filegroup({
  srcs: S.glob(["**/*.test.ts", "**/*.test-d.ts", "**/*.bench.ts", "**/*.bench-d.ts"]),
})

// The CJS emit needs a different trustedSetups implementation. Upstream
// swaps the file with mv before and after the compile
// (build:trustedSetups:start/end). Overlay is a derived filegroup with one
// member substituted, so the CJS build compiles the right file without
// mutating the tree.
const cjsSources = S.Overlay({
  base: srcs,
  replace: { "node/trustedSetups.ts": S.file("node/trustedSetups_cjs.ts") },
})

// Literal materializes a fixed file, replacing the printf > package.json
// stamps in the build scripts.
const esmStamp = S.Literal({
  path: "_esm/package.json",
  content: '{"type":"module","sideEffects":false}',
})

const cjsStamp = S.Literal({
  path: "_cjs/package.json",
  content: '{"type":"commonjs"}',
})

const typesStamp = S.Literal({
  path: "_types/package.json",
  content: '{"type":"module"}',
})

const compileEsm = S.Shell.Build({
  bin: S.NodeModule.Bin("typescript", "tsc"),
  args: ["--project", "tsconfig.build.json", "--outDir", "./src/_esm"],
  data: [srcs, buildTsconfig, baseTsconfig],
  outDirs: ["_esm"],
})

const buildEsm = S.Filegroup({
  srcs: [compileEsm, esmStamp],
})

// Upstream wraps tsc in scripts/runTsc.js only to pass CLI overrides; the
// rule passes them directly.
const compileCjs = S.Shell.Build({
  bin: S.NodeModule.Bin("typescript", "tsc"),
  args: [
    "--project", "tsconfig.build.json",
    "--module", "commonjs",
    "--moduleResolution", "node",
    "--outDir", "./src/_cjs",
    "--removeComments",
    "--verbatimModuleSyntax", "false",
  ],
  data: [cjsSources, buildTsconfig, baseTsconfig],
  outDirs: ["_cjs"],
})

const buildCjs = S.Filegroup({
  srcs: [compileCjs, cjsStamp],
})

const compileTypes = S.Shell.Build({
  bin: S.NodeModule.Bin("typescript", "tsc"),
  args: [
    "--project", "tsconfig.build.json",
    "--declarationDir", "./src/_types",
    "--emitDeclarationOnly",
    "--declaration",
    "--declarationMap",
    "--incremental", "false",
  ],
  data: [srcs, buildTsconfig, baseTsconfig],
  outDirs: ["_types"],
})

const buildTypes = S.Filegroup({
  srcs: [compileTypes, typesStamp],
})

// The publishable package: the three emits the exports map in
// src/package.json points at.
const build = S.Filegroup({
  srcs: [buildEsm, buildCjs, buildTypes],
})

// version:update writes the package version into errors/version.ts so
// runtime error URLs carry it.
const version = S.Generate({
  bin: S.NodeModule.Bin("bun"),
  args: ["scripts/updateVersion.ts"],
  data: [packageJson],
  changes: ["errors/version.ts"],
})

// gen:tempo-abis derives ABI and selector tables plus a test fixture.
// changes uses absolute labels because the generator writes across
// packages.
const tempoAbis = S.Generate({
  bin: S.NodeModule.Bin("bun"),
  args: ["scripts/generateTempoAbis.ts"],
  data: [srcs],
  changes: [
    "//src/tempo/Abis.ts",
    "//src/tempo/Selectors.ts",
    "//test/src/tempo/earnContracts.ts",
  ],
})

// gen:tokenlist fetches the upstream token list, so the generator is one
// of the few network targets outside tests.
const tokenlist = S.Generate({
  bin: S.NodeModule.Bin("bun"),
  args: ["scripts/generateTokenlist.ts"],
  data: [srcs],
  changes: ["tokens/**"],
  sandbox: { network: true },
})

export const Package = S.Package({
  targets: {
    build,
    buildCjs,
    buildEsm,
    buildTypes,
    srcs,
    tempoAbis,
    tests,
    tokenlist,
    version,
  },
})

/// <reference path="../smithers.d.ts" />
import { Smithers as S } from "@smthrs/targets"
import { Package as src } from "../src/PACKAGE.js"

const srcs = S.Filegroup({
  srcs: S.glob(["**", "!**/*.json"]),
})

// Cross-implementation vectors: generate.ts derives cases from independent
// oracles (@ethereumjs/rlp, micro-eth-signer, ethers). The json is a build
// artifact (gitignored upstream), so generation is a Build and the test
// replays its output against viem.
const generate = S.Shell.Build({
  bin: S.NodeModule.Bin("bun"),
  args: ["vectors/generate.ts"],
  data: [srcs, src.srcs],
  outFiles: ["**/*.json"],
})

const test = S.Shell.Test({
  bin: S.NodeModule.Bin("bun"),
  args: ["test", "vectors"],
  data: [srcs, generate, src.srcs],
})

export const Package = S.Package({
  targets: { generate, srcs, test },
})

/// <reference path="./smithers.d.ts" />
import { Smithers as S } from "@smthrs/targets"

const packageJson = S.file("//package.json")
const lockfile = S.file("//pnpm-lock.yaml")
const workspaceConfig = S.file("//pnpm-workspace.yaml")

// engines.node (>=24.5) comes from the manifest.
const runtime = S.Runtime.Node({ manifest: packageJson })

// packageManager pins pnpm@11.13.1. The workspace file carries the package
// globs, the typescript catalog pin, the dependency overrides, and the
// audit allowlist; passing it makes those graph inputs, so an override
// bump invalidates exactly the targets that resolve through it.
const packageManager = S.PackageManager.Pnpm({
  manifest: packageJson,
  lockfile,
  workspaces: workspaceConfig,
})

const nodeModules = S.Npm.NodeModules({
  packageJson,
  workspaces: workspaceConfig,
})

// forge and anvil come from the host foundry install (CI pins v1.7.1),
// docker backs the tempo localnet containers, git materializes the
// contract submodules.
const host = S.Host({
  bins: ["forge", "anvil", "docker", "git"],
})

export const Workspace = S.Workspace("viem", {
  repository: "git+https://github.com/wevm/viem.git",
  cache: S.Cache({ directory: ".flows" }),
  runtime,
  packageManager,
  nodeModules,
  host,
})

